// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0 && amount < type(uint256).max / 2);
        vm.assume(actor != address(0) && actor != address(c));

        // fund the actor and credit their balance via the fallback
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool okPay, ) = address(c).call{value: amount}("");
        assertTrue(okPay);

        // withdraw through the public entry
        vm.prank(actor);
        try c.withdraw() {
            // GENERAL RULE: after a completed withdraw, the caller's balance is zero
            assertTrue(c.balances(actor) == 0, "balance must be zeroed after withdraw");
        } catch {
            // if withdraw reverted, the balance must still be the deposited amount (unchanged rule still holds)
            assertTrue(c.balances(actor) == amount);
        }
    }
}
